// Original technical diagrams, drawn as vector shapes so they remain crisp at any window size.
public static class PartArt {
    public static void Draw(Graphics g,string key,Rectangle rect){var saved=g.Save();g.SetClip(rect,CombineMode.Intersect);g.TranslateTransform(rect.X,rect.Y);g.ScaleTransform(rect.Width/180f,rect.Height/100f);g.SmoothingMode=SmoothingMode.AntiAlias;using(var grid=new Pen(Color.FromArgb(35,130,140,160),.6f)){for(int x=10;x<180;x+=20)g.DrawLine(grid,x,0,x,100);for(int y=10;y<100;y+=20)g.DrawLine(grid,0,y,180,y);}using(var white=new Pen(Color.FromArgb(226,226,226),2))using(var red=new Pen(Theme.Red,3))using(var dim=new Pen(Color.FromArgb(112,112,112),1.4f))using(var fill=new SolidBrush(Color.FromArgb(45,45,45))){
        switch(key){
        case "front":for(int i=0;i<3;i++){g.DrawBezier(i==1?red:white,15,35+i*10,55,20+i*10,125,60+i*6,165,35+i*10);}g.DrawLine(white,15,28,15,78);g.DrawLine(white,165,28,165,78);g.DrawLine(red,75,30,82,75);g.DrawLine(red,100,30,97,75);break;
        case "rear":for(int i=0;i<3;i++)g.DrawPolygon(i==1?red:white,new[]{new Point(30,25+i*13),new Point(140,20+i*13),new Point(160,30+i*13),new Point(40,37+i*13)});g.DrawLine(white,65,58,65,87);g.DrawLine(white,125,55,125,85);break;
        case "floor":g.FillPolygon(fill,new[]{new Point(30,20),new Point(143,15),new Point(167,79),new Point(15,84)});g.DrawPolygon(white,new[]{new Point(30,20),new Point(143,15),new Point(167,79),new Point(15,84)});for(int i=0;i<5;i++)g.DrawBezier(i==2?red:dim,40+i*20,27,25+i*25,43,40+i*20,58,30+i*25,76);break;
        case "diffuser":g.DrawPolygon(white,new[]{new Point(35,24),new Point(135,24),new Point(165,79),new Point(15,79)});for(int i=0;i<5;i++)g.DrawLine(i%2==0?red:white,45+i*20,28,30+i*28,75);break;
        case "mono":g.FillPolygon(fill,new[]{new Point(50,15),new Point(123,15),new Point(150,76),new Point(104,88),new Point(42,73),new Point(25,39)});g.DrawPolygon(white,new[]{new Point(50,15),new Point(123,15),new Point(150,76),new Point(104,88),new Point(42,73),new Point(25,39)});g.DrawEllipse(red,65,22,43,45);g.DrawLine(dim,35,42,135,69);break;
        case "nose":g.DrawPolygon(white,new[]{new Point(30,24),new Point(140,45),new Point(160,57),new Point(140,69),new Point(30,74)});g.DrawLine(red,40,30,140,52);g.DrawLine(red,40,68,140,59);g.DrawEllipse(dim,25,24,16,50);break;
        case "sidepods":for(int i=0;i<2;i++){int y=16+i*44;g.DrawBezier(white,20,y+19,45,y-3,110,y+1,158,y+27);g.DrawBezier(red,20,y+19,55,y+42,110,y+35,158,y+27);g.DrawEllipse(dim,20,y+11,28,18);}break;
        case "suspF":case "suspR":g.DrawRectangle(white,12,21,24,58);g.DrawRectangle(white,144,21,24,58);g.DrawLine(white,38,30,87,69);g.DrawLine(white,38,70,87,35);g.DrawLine(white,142,30,95,69);g.DrawLine(white,142,70,95,35);g.DrawLine(red,40,46,140,46);g.DrawLine(red,85,24,96,78);if(key=="suspR")for(int i=0;i<5;i++)g.DrawLine(dim,80,30+i*8,102,36+i*8);break;
        case "brakes":g.DrawEllipse(white,48,12,80,80);g.DrawEllipse(red,58,22,60,60);g.DrawEllipse(white,75,39,26,26);for(int i=0;i<12;i++){double a=i*Math.PI/6;g.DrawEllipse(dim,(float)(86+32*Math.Cos(a)),(float)(50+32*Math.Sin(a)),4,4);}g.DrawRectangle(red,121,29,15,41);break;
        case "radiators":g.DrawPolygon(white,new[]{new Point(35,14),new Point(145,24),new Point(135,88),new Point(25,76)});for(int i=0;i<13;i++)g.DrawLine(i%4==0?red:dim,38+i*8,22,29+i*8,74);g.DrawLine(white,42,28,140,38);g.DrawLine(white,37,55,135,66);break;
        case "ducts":g.DrawBezier(red,25,25,60,10,100,79,153,60);g.DrawBezier(white,25,62,65,39,99,100,153,78);g.DrawEllipse(white,12,21,30,45);g.DrawEllipse(red,143,57,24,23);break;
        case "gearbox":g.DrawPolygon(white,new[]{new Point(45,19),new Point(125,22),new Point(150,61),new Point(113,83),new Point(37,75),new Point(22,40)});g.DrawEllipse(red,50,35,40,40);g.DrawEllipse(white,92,40,29,29);g.DrawLine(white,10,55,47,55);g.DrawLine(white,123,55,167,55);break;
        case "electronics":g.DrawRectangle(white,30,17,120,68);g.DrawRectangle(red,70,33,42,35);for(int i=0;i<5;i++){g.DrawLine(dim,36,27+i*12,66,27+i*12);g.DrawLine(dim,115,27+i*12,146,27+i*12);g.DrawEllipse(red,37,25+i*12,4,4);}break;
        case "hydraulics":g.DrawRectangle(white,26,35,85,29);g.DrawLine(red,112,44,163,44);g.DrawLine(red,112,56,163,56);g.DrawBezier(white,40,35,30,4,118,9,118,34);g.DrawEllipse(red,14,33,23,33);break;
        }
    }g.Restore(saved);}
}
public class PartPicture:Control {public string PartKey;public PartPicture(string key){PartKey=key;DoubleBuffered=true;BackColor=Theme.Card;}protected override void OnPaint(PaintEventArgs e){PartArt.Draw(e.Graphics,PartKey,ClientRectangle);}}
public class DevelopmentOverlay:GameOverlay {
    readonly Career state;readonly Component part;readonly int free;readonly bool nextYear;Label estimate,impacts,error;
    internal readonly SliderInput Engineers=new SliderInput{Caption="Назначенные инженеры",Increment=1};
    internal readonly SoftButton StartButton=new SoftButton{Text="Запустить разработку",Primary=true},BackButton=new SoftButton{Text="Назад"};
    public event Action Started,Cancelled;
    protected override Size SheetSize {get{return new Size(920,650);}}
    public DevelopmentOverlay(Career career,Component component,bool animated,bool future=false):base(animated){nextYear=future;state=career;part=component;var team=Engine.Team(state,state.Player);free=Engine.Capacity(team)-Engine.Assigned(state,team);LabelAt(Sheet,nextYear?"БОЛИД "+(state.Year+1)+" / РАЗРАБОТКА":"РАЗРАБОТКА ДЕТАЛИ",32,22,850,35,25,true,Color.White);LabelAt(Sheet,part.Name,250,86,610,37,23,true,Color.White);LabelAt(Sheet,part.Description,252,132,600,56,14);Sheet.Controls.Add(new PartPicture(part.Key){Bounds=new Rectangle(32,80,195,123)});Engineers.SetRange(1,Math.Max(1,free));Engineers.Value=1;Engineers.Enabled=free>0;Engineers.Bounds=new Rectangle(32,224,856,62);Engineers.Caption="Инженеры / свободно "+free;Sheet.Controls.Add(Engineers);estimate=LabelAt(Sheet,"",32,308,400,165,15);impacts=LabelAt(Sheet,"",458,307,425,180,13);LabelAt(Sheet,nextYear?"Общий бюджет текущего сезона. Деталь не улучшит нынешний болид — она будет установлена в "+(state.Year+1)+" году.":"Показатели уточняются после проверки на трассе. Слот и инженеры заняты до поставки детали.",32,493,850,50,13);error=LabelAt(Sheet,free>0?"":"Нет свободных инженеров. Дождитесь поставки детали.",32,548,850,30,12,false,Theme.Red);Sheet.Controls.Add(StartButton);Sheet.Controls.Add(BackButton);StartButton.Enabled=free>0;StartButton.Bounds=new Rectangle(535,586,353,43);BackButton.Bounds=new Rectangle(32,586,150,43);Engineers.ValueChanged+=(o,e)=>UpdateEstimate();StartButton.Click+=(o,e)=>{try{Engine.Develop(state,part.Key,(int)Engineers.Value,nextYear);if(Started!=null)Started();}catch(Exception ex){error.Text=ex.Message;}};BackButton.Click+=(o,e)=>Cancel();UpdateEstimate();}
    void UpdateEstimate(){var project=Engine.Estimate(state,part,(int)Engineers.Value,nextYear);estimate.Text="Стоимость: "+Engine.Money(project.Cost)+"\nПроектирование: "+(project.DesignEnd-state.Day)+" дн.\nПроизводство: "+(project.Due-project.DesignEnd)+" дн.\nПоставка: день "+project.Due+"\nРиск провала стенда: "+(project.Failure*100).ToString("0.0")+"%";var effects=CarModel.Effects(part.Key,project.Gain);impacts.Text="ОЖИДАЕМЫЕ ИЗМЕНЕНИЯ\n"+string.Join("\n",Enumerable.Range(0,10).Where(i=>effects[i]!=0).Select(i=>CarModel.Names[i]+"  "+effects[i].ToString("+0.00;-0.00;0")));}
    public override void Cancel(){if(!Closing&&Cancelled!=null)Cancelled();}
}
